<?php defined('BASEPATH') or exit('No direct script access allowed'); init_head(); ?><div id="wrapper"><div id="sc-enterprise-app"><div class="content"><div class="sc-enterprise-header"><div><h1><?php echo html_escape($title); ?></h1><p><?php echo _l('enterprise_reporting_description'); ?></p></div><div class="sc-toolbar"><a class="btn btn-default btn-sm" href="<?php echo current_url(); ?>"><i class="fa fa-refresh"></i> <?php echo _l('reload'); ?></a></div></div><div class="row"><?php foreach($core_totals as $label=>$count){?><div class="col-md-3 col-sm-6"><div class="panel_s sc-metric-card"><div class="panel-body"><i class="fa fa-bar-chart"></i><div><span><?php echo html_escape(ucwords($label)); ?></span><strong><?php echo (int)$count; ?></strong></div></div></div></div><?php }?></div><div class="row"><div class="col-md-6"><div class="panel_s"><div class="panel-body"><h4><?php echo _l('enterprise_invoice_value'); ?></h4><h2><?php echo app_format_money($invoice_value,$currency); ?></h2></div></div></div><div class="col-md-6"><div class="panel_s"><div class="panel-body"><h4><?php echo _l('enterprise_payments_received'); ?></h4><h2><?php echo app_format_money($payments_value,$currency); ?></h2></div></div></div></div></div></div></div><?php init_tail(); ?>